select n.id as id from notes n  left join (select rank_copy_n.copied_from_note_id as note_id, count(*) as metric from notes rank_copy_n where rank_copy_n.copied_from_public = true and rank_copy_n.copied_from_note_id is not null group by rank_copy_n.copied_from_note_id) rank_copies on rank_copies.note_id = n.id  where n.visibility = 'PUBLIC' order by coalesce(rank_copies.metric, 0) desc, n.created_at desc, n.id asc fetch first ? rows only